public sealed interface Shape permits Circle, Rectangle {}
public record Point(int x, int y) {}
public record Circle(Point center, int radius) implements Shape {}
public record Rectangle(Point topLeft, int width, int height) implements Shape {}

public class ShapeAnalyzer {
    public static void describeShape(Shape shape) {
        switch (shape) {
            case Circle(Point(var x, var y), var r) -> 
                System.out.println("Circle at (" + x + ", " + y + ") with radius " + r);
            case Rectangle(Point(var x, var y), var w, var h) -> 
                System.out.println("Rectangle at (" + x + ", " + y + ") with dimensions " + w + "x" + h);
            default -> 
                System.out.println("Unknown shape");
        }
    }
}
